from modele import chapitre,E,Q

chapitre(16,'cercle','Triangle rectangle et cercle circonscrit','4 · Géométrie et espace',
'Demi-cercle · Centre · Médiane · Rectangles sans équerre',
['Caractériser un triangle rectangle par son cercle circonscrit.','Déterminer le centre du cercle circonscrit d’un triangle rectangle.','Construire un angle droit ou un rectangle sans équerre.'],
['Médiatrices, droite des milieux et théorème de Pythagore (chapitres 12, 14 et 15).'],[
r'''\essSection{1}{Le cercle d’un triangle rectangle}
\begin{theoreme}Si un triangle est rectangle, alors le centre de son cercle circonscrit est le milieu de son hypoténuse : le triangle est inscrit dans un demi-cercle dont l’hypoténuse est un diamètre. Ainsi, la médiane issue du sommet de l’angle droit mesure la moitié de l’hypoténuse.\end{theoreme}
@FIG:cours-cercle@
\begin{demonstration}ABC est rectangle en A ; I est le milieu de $[BC]$ et J celui de $[AB]$. D’après la droite des milieux, $(IJ)\parallel(AC)$ ; comme $(AC)\perp(AB)$, on a $(IJ)\perp(AB)$. La droite $(IJ)$ est donc la médiatrice de $[AB]$, d’où $IA=IB$. Comme $IB=IC$, I est équidistant des trois sommets : c’est le centre du cercle circonscrit.\end{demonstration}
\begin{exemple}ABC est rectangle en A avec $BC=10$ cm. Le cercle circonscrit a pour centre le milieu I de $[BC]$ et pour rayon 5 cm ; la médiane $[AI]$ mesure 5 cm.\end{exemple}''',
r'''\essSection{2}{Reconnaître un triangle rectangle}
\begin{theoreme}[Réciproque]Si un triangle est inscrit dans un cercle qui a pour diamètre l’un de ses côtés, alors ce triangle est rectangle ; l’angle droit est opposé à ce diamètre. Autrement dit, si la médiane issue d’un sommet mesure la moitié du côté opposé, le triangle est rectangle en ce sommet.\end{theoreme}
\begin{demonstration}A est sur le cercle de diamètre $[BC]$ et de centre O. Le demi-tour de centre O transforme A en A’. Les diagonales $[BC]$ et $[AA']$ de ABA’C ont le même milieu O et la même longueur, celle d’un diamètre : ABA’C est un rectangle, donc $\widehat{BAC}=90^\circ$.\end{demonstration}
\begin{savoirfaire}[Construire sans équerre]Pour un rectangle : tracer un cercle et deux de ses diamètres $[AC]$ et $[BD]$ ; ABCD a des diagonales de même milieu et de même longueur, c’est un rectangle. Pour un angle droit en A sur une droite $(d)$ : un cercle passant par A recoupe $(d)$ en B ; si $[BC]$ est un diamètre, $(AC)\perp(d)$.\end{savoirfaire}
\begin{attention}Un triangle inscrit dans un cercle n’est rectangle que si l’un de ses côtés est un diamètre. Le codage ou l’énoncé doit le garantir ; l’aspect du dessin ne suffit pas.\end{attention}'''],[
E('Trouver le centre',r"ABC est rectangle en A et $BC=9$ cm. Où se trouve le centre de son cercle circonscrit ? Quel est le rayon de ce cercle ?",r"ABC est rectangle en A, donc le centre de son cercle circonscrit est le $\res{\text{milieu de l’hypoténuse }[BC]}$. Le rayon vaut $\frac92=\res{4{,}5\ \mathrm{cm}}$.","Repérer l’hypoténuse, côté opposé à l’angle droit.","assert Rational(9,2)==Rational('4.5')",figure='cer-01'),
E('Une médiane',r"ABC est rectangle en A, $BC=13$ cm et I est le milieu de $[BC]$. Calculer AI.",r"Dans un triangle rectangle, la médiane issue du sommet de l’angle droit mesure la moitié de l’hypoténuse : $AI=\frac{13}2=\res{6{,}5\ \mathrm{cm}}$.","Utiliser le milieu de l’hypoténuse.","assert Rational(13,2)==Rational('6.5')",figure='cer-02'),
E('Un angle droit garanti',r"Les points B et C sont les extrémités d’un diamètre d’un cercle ; A est un autre point de ce cercle. Que peut-on dire du triangle ABC ?",r"ABC est inscrit dans un cercle dont un diamètre est son côté $[BC]$. D’après la réciproque, $\res{\text{ABC est rectangle en A}}$, sommet opposé au diamètre.","Vérifier qu’un côté est un diamètre.","import math as m; A=(m.cos(1),m.sin(1)); B=(-1,0); C=(1,0); assert abs((B[0]-A[0])*(C[0]-A[0])+(B[1]-A[1])*(C[1]-A[1]))<1e-12",figure='cer-03'),
E('Le rayon par Pythagore',r"ABC est rectangle en A, avec $AB=6$ cm et $AC=8$ cm. Calculer le rayon de son cercle circonscrit.",r"Le théorème de Pythagore donne $BC=\sqrt{36+64}=10$ cm. Le centre du cercle circonscrit est le milieu de l’hypoténuse : le rayon vaut $\frac{10}2=\res{5\ \mathrm{cm}}$.","Calculer l’hypoténuse, puis sa moitié.","assert sqrt(6**2+8**2)/2==5",figure='cer-04'),
E('Vrai ou faux ?',r"Affirmation : « Tout triangle inscrit dans un cercle est rectangle. » Est-elle vraie ?",r"Elle est $\res{\text{fausse}}$. Un triangle équilatéral inscrit dans un cercle est un contre-exemple : ses trois angles mesurent $60^\circ$. Aucun de ses côtés n’est un diamètre.","Chercher un contre-exemple.","assert 3*60==180 and 60!=90",figure='cer-05'),
E('Une médiane qui décide',r"Dans le triangle ABC, I est le milieu de $[BC]$, $BC=7$ cm et $AI=3{,}5$ cm. Démontrer que ABC est rectangle.",r"$IA=IB=IC=3{,}5$ cm : A est sur le cercle de centre I et de rayon 3,5 cm, qui a pour diamètre $[BC]$. Le triangle ABC est inscrit dans ce cercle avec $[BC]$ comme diamètre : $\res{\text{il est rectangle en A}}$.","Montrer que A est sur le cercle de diamètre [BC].","assert Rational(7,2)==Rational('3.5')",figure='cer-06'),
E('Calculer un angle',r"$[AB]$ est un diamètre d’un cercle et C un point de ce cercle, distinct de A et B. On sait que $\widehat{ABC}=32^\circ$. Calculer $\widehat{BAC}$.",r"Le triangle ABC est inscrit dans le cercle de diamètre $[AB]$ : il est rectangle en C. La somme des angles donne $\widehat{BAC}=180-90-32=\res{58^\circ}$.","Trouver d’abord l’angle droit.","assert 180-90-32==58",figure='cer-07'),
E('Un rectangle sans équerre',r"On trace un cercle de centre O et de rayon 4 cm, puis deux diamètres $[AC]$ et $[BD]$ non perpendiculaires. Démontrer que ABCD est un rectangle et donner la longueur de ses diagonales.",r"Les diagonales $[AC]$ et $[BD]$ ont le même milieu O : ABCD est un parallélogramme. Elles ont la même longueur, celle d’un diamètre, $\res{8\ \mathrm{cm}}$. Un parallélogramme dont les diagonales ont la même longueur est un $\res{\text{rectangle}}$.","Utiliser les propriétés des diagonales.","assert 2*4==8",figure='cer-08'),
E('Des triangles rectangles en M',r"A et B sont deux points tels que $AB=6$ cm. Où placer un point M pour que le triangle AMB soit rectangle en M ? Justifier.",r"Si AMB est rectangle en M, son cercle circonscrit a pour diamètre $[AB]$ : M est sur le cercle de diamètre $[AB]$. Réciproquement, tout point de ce cercle, autre que A et B, convient. Ce sont les points du $\res{\text{cercle de centre le milieu de }[AB]\text{ et de rayon 3 cm}}$, sauf A et B.","Utiliser le théorème et sa réciproque.","assert Rational(6,2)==3",figure='cer-09'),
E('Avec Pythagore',r"$[AB]$ est un diamètre d’un cercle de rayon 5 cm, et C un point du cercle tel que $AC=6$ cm. Calculer BC.",r"ABC est inscrit dans le cercle de diamètre $[AB]$ : il est rectangle en C, avec $AB=10$ cm. Pythagore donne $BC^2=10^2-6^2=64$, donc $\res{BC=8\ \mathrm{cm}}$.","Identifier l’angle droit avant d’appliquer Pythagore.","assert sqrt(10**2-6**2)==8",figure='cer-10'),
E('Une perpendiculaire au compas',r"A est un point d’une droite $(d)$. On choisit un point O hors de $(d)$ ; le cercle de centre O passant par A recoupe $(d)$ en B. On trace le diamètre $[BC]$. Démontrer que $(AC)$ est perpendiculaire à $(d)$.",r"A est sur le cercle de diamètre $[BC]$, distinct de B et C : le triangle ABC est rectangle en A. Donc $(AC)\perp(AB)$, c’est-à-dire $\res{(AC)\perp(d)}$. La construction n’utilise que la règle et le compas.","Reconnaître un triangle inscrit dans un demi-cercle.","O=(1,2); A=(0,0); B=(2,0); C=(2*O[0]-B[0],2*O[1]-B[1]); assert (O[0]-A[0])**2+(O[1]-A[1])**2==(O[0]-B[0])**2+(O[1]-B[1])**2 and (C[0]-A[0])*(B[0]-A[0])+(C[1]-A[1])*(B[1]-A[1])==0",figure='cer-11'),
E('Dans un demi-cercle',r"Un demi-cercle a pour diamètre $[AB]$ avec $AB=10$ cm. Le point C du demi-cercle vérifie $AC=BC$. Calculer AC, exactement puis au centième, et l’aire du triangle ABC.",r"ABC est rectangle en C et isocèle. Pythagore donne $AC^2+BC^2=100$, donc $2AC^2=100$ et $AC^2=50$ : $\res{AC=\sqrt{50}\ \mathrm{cm}}\approx\res{7{,}07\ \mathrm{cm}}$. L’aire vaut $\frac{AC\times BC}2=\frac{50}2=\res{25\ \mathrm{cm}^2}$.","Combiner l’angle droit et les côtés égaux.","assert 2*50==100 and round(float(sqrt(50)),2)==7.07 and Rational(50,2)==25",figure='cer-12'),
E('Distance du centre à un côté',r"ABC est rectangle en A, avec $AB=5$ cm et $AC=12$ cm. O est le centre de son cercle circonscrit et J le milieu de $[AB]$. Calculer le rayon du cercle et la longueur OJ.",r"$BC=\sqrt{25+144}=13$ cm, donc le rayon vaut $\res{6{,}5\ \mathrm{cm}}$, et O est le milieu de $[BC]$. Dans ABC, O et J sont les milieux de $[BC]$ et $[AB]$ : $OJ=\frac{AC}2=\res{6\ \mathrm{cm}}$ et $(OJ)\parallel(AC)$, donc $(OJ)\perp(AB)$.","Utiliser le cercle puis la droite des milieux.","assert sqrt(5**2+12**2)/2==Rational(13,2) and Rational(12,2)==6",figure='cer-13'),
E('Un rectangle inscrit',r"Un rectangle ABCD est inscrit dans un cercle de rayon 6,5 cm, et $AB=5$ cm. Calculer BC puis l’aire du rectangle.",r"Les diagonales d’un rectangle ont le même milieu et la même longueur : ce milieu est le centre du cercle et $AC=13$ cm est un diamètre. ABC est rectangle en B, donc $BC=\sqrt{13^2-5^2}=\res{12\ \mathrm{cm}}$. L’aire vaut $5\times12=\res{60\ \mathrm{cm}^2}$.","Reconnaître que la diagonale est un diamètre.","assert sqrt(13**2-5**2)==12 and 5*12==60",figure='cer-14'),
E('Sans mesurer d’angle',r"Sur un cercle de centre O et de rayon 4 cm, on place B et C tels que O appartienne à $[BC]$, puis un point A du cercle tel que $AB=5$ cm. Calculer AC exactement, puis au centième. Pourquoi n’a-t-on pas besoin de mesurer un angle ?",r"O est sur $[BC]$ et $OB=OC=4$ cm : $[BC]$ est un diamètre de 8 cm. Le triangle ABC, inscrit dans le cercle de diamètre $[BC]$, est rectangle en A. Donc $AC^2=64-25=39$ : $\res{AC=\sqrt{39}\ \mathrm{cm}}\approx\res{6{,}24\ \mathrm{cm}}$. L’angle droit est démontré par la réciproque, pas mesuré.","Démontrer l’angle droit, puis appliquer Pythagore.","assert 8**2-5**2==39 and round(float(sqrt(39)),2)==6.24",figure='cer-15')
],reperes=['Centre du cercle et milieu de l’hypoténuse','Médiane et moitié de l’hypoténuse','Réciproque : triangle inscrit dans un demi-cercle','Constructions sans équerre et problèmes'],deco='cercle')

chapitre(17,'solides','Pyramides et cônes','4 · Géométrie et espace',
'Reconnaître · Perspective · Patron · Volume',
['Reconnaître une pyramide, un cône de révolution et les autres solides usuels.','Relier perspective cavalière et patron d’une pyramide ou d’un cône.','Calculer les volumes d’une pyramide et d’un cône.'],
['Aires usuelles, volumes du pavé, du prisme et du cylindre, Pythagore.'],[
r'''\essSection{1}{Reconnaître et représenter}
\begin{definition}Une pyramide a une base polygonale et des faces latérales triangulaires qui se rejoignent en un sommet. Un cône de révolution est obtenu en faisant tourner un triangle rectangle autour d’un côté de l’angle droit : sa base est un disque, sa hauteur joint le sommet au centre de la base et une génératrice joint le sommet au cercle de base.\end{definition}
\begin{savoirfaire}[Distinguer les solides]Un prisme droit ou un cylindre a deux bases superposables et parallèles. Une pyramide ou un cône a une seule base et un sommet. La base d’une pyramide peut être un triangle, un carré ou un autre polygone.\end{savoirfaire}
@FIG:cours-solides@
\begin{savoirfaire}[Perspective et patron]La perspective cavalière dessine les arêtes cachées en pointillés ; elle ne conserve pas toutes les longueurs ni tous les angles. Un patron est une figure plane qui reconstitue le solide par pliage : les côtés assemblés doivent avoir la même longueur. Pour un cône, l’arc du secteur latéral a la longueur du cercle de base.\end{savoirfaire}''',
r'''\essSection{2}{Des volumes liés à une base}
\begin{propriete}Pour une pyramide, $V=\frac13\mathcal B\times h$, où $\mathcal B$ est l’aire de la base et $h$ la hauteur, perpendiculaire au plan de base. Pour un cône de rayon $r$, $V=\frac13\pi r^2h$. Il faut le contenu de trois pyramides pour remplir un prisme de même base et de même hauteur ; de même pour un cône et un cylindre.\end{propriete}
\begin{exemple}Une pyramide de base carrée de côté 6 cm et de hauteur 8 cm a pour volume $\frac13\times36\times8=96$ cm$^3$. Un cône de rayon 3 cm et de hauteur 5 cm a pour volume $\frac13\pi\times9\times5=15\pi$ cm$^3$.\end{exemple}
\begin{savoirfaire}[Choisir les bonnes données]Calculer l’aire de la base avant le volume. La hauteur est perpendiculaire à la base : ce n’est ni une arête inclinée ni une génératrice. Convertir les longueurs dans une même unité avant de les multiplier : une aire en cm$^2$ multipliée par une hauteur en cm donne un volume en cm$^3$.\end{savoirfaire}
\begin{attention}La perspective peut écraser une hauteur ou un angle droit : se fier aux données et aux codages, sans mesurer le dessin. Pour un cône, diviser le diamètre par 2 avant d’utiliser le rayon dans $\pi r^2$.\end{attention}
\begin{exemple}[Repère culturel]La pyramide du Louvre, à Paris, est une pyramide de verre à base carrée ; les pyramides de Gizeh, en Égypte, ont aussi une base carrée. Le défi D17 étudie un modèle de la première.\end{exemple}'''],[
E('Nommer les éléments',r"Une pyramide SABCD a pour base le carré ABCD. Nommer son sommet, sa base et ses faces latérales.",r"Le sommet est $\res S$, la base est le carré $\res{ABCD}$. Il y a $\res4$ faces latérales triangulaires : SAB, SBC, SCD et SDA. Avec la base, le solide a cinq faces.","Distinguer base et faces latérales.","assert len(['SAB','SBC','SCD','SDA'])==4",figure='sol-01'),
E('Une pyramide à base carrée',r"Une pyramide a une base carrée de côté 6 cm et une hauteur de 8 cm. Calculer son volume.",r"L’aire de la base vaut $6^2=36$ cm$^2$. Le volume est $V=\frac{36\times8}3=\res{96\ \mathrm{cm}^3}$. La hauteur donnée est perpendiculaire à la base.","Calculer d’abord l’aire de base.","assert Rational(6**2*8,3)==96",figure='sol-02'),
E('Un cône',r"Un cône a pour rayon 3 cm et pour hauteur 5 cm. Donner son volume exact, puis arrondi au dixième de cm$^3$.",r"$V=\frac{\pi\times3^2\times5}3=\res{15\pi\ \mathrm{cm}^3}$. Numériquement, $V\approx\res{47{,}1\ \mathrm{cm}^3}$. On garde $\pi$ pour la valeur exacte.","Appliquer la formule avec le rayon.","assert round(float(15*pi),1)==47.1",figure='sol-03'),
E('Du diamètre au rayon',r"Un cône a une base de diamètre 8 cm et une hauteur de 9 cm. Calculer son volume exact.",r"Le rayon vaut $8:2=4$ cm. Donc $V=\frac{\pi\times4^2\times9}3=\res{48\pi\ \mathrm{cm}^3}$. Utiliser 8 comme rayon multiplierait l’aire de base par 4.","Diviser le diamètre par deux.","assert simplify(pi*Rational(8,2)**2*Rational(9,3))==48*pi",figure='sol-04'),
E('Reconnaître des solides',r"Nommer chacun des quatre solides représentés et préciser le nombre et la forme de ses bases.",r"Solide 1 : $\res{\text{prisme droit}}$ à deux bases triangulaires. Solide 2 : $\res{\text{pyramide}}$ à une base carrée. Solide 3 : $\res{\text{cylindre de révolution}}$ à deux bases en forme de disque. Solide 4 : $\res{\text{cône de révolution}}$ à une base en forme de disque.","Compter les bases et repérer un éventuel sommet.","assert True",figure='sol-05'),
E('Un cône par rotation',r"Le triangle ABC est rectangle en A, avec $AB=4$ cm et $AC=3$ cm. On le fait tourner autour de la droite $(AB)$, puis autour de la droite $(AC)$. Décrire les deux cônes obtenus et comparer leurs volumes.",r"Autour de $(AB)$ : cône de hauteur 4 cm et de rayon 3 cm, de volume $\frac{\pi\times9\times4}3=\res{12\pi\ \mathrm{cm}^3}$. Autour de $(AC)$ : cône de hauteur 3 cm et de rayon 4 cm, de volume $\frac{\pi\times16\times3}3=\res{16\pi\ \mathrm{cm}^3}$. Le second est le plus grand. Dans les deux cas, la génératrice vaut $BC=5$ cm.","Identifier l’axe de rotation, qui porte la hauteur.","assert Rational(9*4,3)==12 and Rational(16*3,3)==16 and sqrt(4**2+3**2)==5",figure='sol-06'),
E('Base triangulaire',r"Une pyramide a pour base un triangle dont un côté mesure 8 cm et la hauteur associée 3 cm. La hauteur de la pyramide vaut 10 cm. Calculer son volume.",r"L’aire de la base vaut $\frac{8\times3}2=12$ cm$^2$. La hauteur du solide, 10 cm, est différente de la hauteur du triangle de base. $V=\frac{12\times10}3=\res{40\ \mathrm{cm}^3}$.","Distinguer hauteur de la base et hauteur du solide.","assert Rational(8*3,2)*Rational(10,3)==40",figure='sol-07'),
E('Retrouver une hauteur',r"Une pyramide a un volume de 150 cm$^3$ et une aire de base de 45 cm$^2$. Déterminer sa hauteur.",r"$150=\frac{45\times h}3=15h$. Donc $h=150:15=\res{10\ \mathrm{cm}}$. On obtient une longueur en divisant un volume par une aire.","Isoler la hauteur dans la formule.","assert Rational(3*150,45)==10",figure='sol-08'),
E('Un patron de pyramide',r"On veut construire le patron d’une pyramide à base carrée de côté 4 cm dont les quatre arêtes latérales mesurent 5 cm. Décrire puis construire ce patron.",r"Tracer un carré de côté 4 cm. Sur chacun de ses côtés, à l’extérieur, construire au compas un triangle isocèle de côtés 5, 5 et 4 cm. Les sommets de ces quatre triangles se rejoindront au pliage. Le patron comporte $\res{\text{un carré et quatre triangles isocèles}}$.","Faire correspondre les côtés qui seront assemblés.","assert 5+5>4",figure='sol-09'),
E('Un patron de cône',r"Un cône a pour rayon de base 3 cm et pour génératrice 5 cm. Représenter ce cône en perspective, puis compléter son patron : un disque de base et un secteur de rayon 5 cm dont on déterminera l’angle.",r"En perspective, la base est une ellipse et les parties cachées sont en pointillés. L’arc du secteur doit mesurer le périmètre de la base, $2\pi\times3=6\pi$ cm. Le cercle de rayon 5 cm a pour périmètre $10\pi$ cm : il faut $\frac6{10}$ de tour, soit $\res{216^\circ}$. La génératrice, et non la hauteur, est le rayon du secteur.","Relier les longueurs de la perspective et du patron.","assert simplify((2*pi*3)/(2*pi*5)*360)==216",figure='sol-10'),
E('Une génératrice calculée',r"Un cône a une hauteur de 12 cm et un rayon de 5 cm. Calculer sa génératrice, puis son volume exact.",r"La hauteur, le rayon et la génératrice forment un triangle rectangle. La génératrice vaut $\sqrt{12^2+5^2}=\res{13}$ cm. Le volume est $\frac{\pi\times5^2\times12}3=\res{100\pi\ \mathrm{cm}^3}$. La génératrice ne remplace pas la hauteur dans la formule.","Séparer le triangle rectangle et la formule du volume.","assert sqrt(12**2+5**2)==13 and Rational(25*12,3)==100",figure='sol-11'),
E('Comparer un cylindre et un cône',r"Un cône et un cylindre ont la même base de rayon 4 cm et la même hauteur de 6 cm. Donner leurs volumes et leur différence.",r"Le cylindre a pour volume $\pi\times16\times6=\res{96\pi}$ cm$^3$. Le cône en a le tiers, soit $\res{32\pi}$ cm$^3$. Leur différence vaut $\res{64\pi\ \mathrm{cm}^3}$.","Utiliser la base et la hauteur communes.","assert 16*6==96 and Rational(16*6,3)==32 and 96-32==64",figure='sol-12'),
E('Deux unités',r"Un réservoir conique a un rayon de 40 cm et une hauteur de 1,2 m. Donner sa capacité en litres, au dixième.",r"On choisit le décimètre : $r=4$ dm et $h=12$ dm. $V=\frac{\pi\times4^2\times12}3=64\pi$ dm$^3$, donc $64\pi$ L, soit environ $\res{201{,}1\ \mathrm L}$. Les unités sont unifiées avant le calcul.","Choisir les décimètres pour obtenir directement des litres.","assert round(float(64*pi),1)==201.1",figure='sol-13'),
E('Un assemblage',r"Un solide est formé d’un pavé droit de 8 cm sur 6 cm sur 4 cm, surmonté d’une pyramide dont la base est la face supérieure du pavé et dont la hauteur vaut 3 cm. Calculer le volume total.",r"Le pavé a pour volume $8\times6\times4=192$ cm$^3$. La pyramide a pour volume $\frac{8\times6\times3}3=48$ cm$^3$. Les deux parties ne se chevauchent pas : le total vaut $\res{240\ \mathrm{cm}^3}$.","Additionner les volumes des deux parties.","assert 8*6*4+Rational(8*6*3,3)==240",figure='sol-14'),
E('Un remplissage partiel',r"Un récipient conique de rayon 6 cm et de hauteur 10 cm est rempli aux trois quarts de sa capacité. Calculer le volume d’eau exact en cm$^3$, puis en mL au dixième. Peut-on en déduire une hauteur d’eau de 7,5 cm ?",r"La capacité vaut $\frac{\pi\times36\times10}3=120\pi$ cm$^3$. L’eau en occupe les trois quarts, soit $\res{90\pi\ \mathrm{cm}^3}\approx\res{282{,}7\ \mathrm{mL}}$. On ne peut pas conclure à une hauteur de 7,5 cm : la largeur du cône change avec la hauteur, donc volume et hauteur d’eau ne sont pas proportionnels.","Appliquer la fraction au volume, sans la transférer à la hauteur.","assert Rational(3,4)*120*pi==90*pi and round(float(90*pi),1)==282.7",figure='sol-15')
],reperes=['Reconnaître pyramides, cônes et solides usuels','Perspective et patrons','Volumes de la pyramide et du cône','Unités, assemblages et problèmes'],deco='espace')

chapitre(18,'programmation','Algorithmique : conditions et variable','5 · Programmer et réinvestir',
'Variable · Conditions · Boucles · Écrire et modifier',
['Manipuler une variable, notamment pour accumuler dans une boucle.','Représenter des conditions simples et écrire des instructions conditionnelles.','Écrire un programme simple et modifier un programme donné.'],
['Séquences d’instructions, entrées, sorties et boucles « répéter n fois » (Cinquième).'],[
r'''\essSection{1}{Variable, séquences et boucles}
\begin{definition}Un algorithme est une suite précise d’instructions qui réalise une tâche ; un programme le traduit dans un langage. Une variable associe un nom à un espace de mémoire dont la valeur peut être lue et modifiée : « mettre x à 3 » remplace son contenu par 3 ; « ajouter 2 à x » l’augmente de 2.\end{definition}
\begin{savoirfaire}[Lire un script]Repérer l’événement de départ, puis suivre les blocs dans l’ordre en notant la valeur de la variable après chaque instruction. Dans une boucle « répéter n fois », toutes les instructions intérieures sont reprises à chaque tour ; dans le livre, les indentations et les lignes « fin » délimitent les blocs.\end{savoirfaire}
@FIG:script-01@
\begin{attention}Une instruction utilise la valeur de la variable au moment où elle est exécutée : permuter deux blocs peut changer le résultat. On initialise la variable avant une boucle qui l’accumule, et non à l’intérieur.\end{attention}''',
r'''\essSection{2}{Conditions et instructions conditionnelles}
\begin{definition}Une condition est une expression vraie ou fausse, construite ici avec les opérateurs $<$, $>$ ou $=$ : « x > 9 », « réponse = 6 ». Le bloc « si … alors … sinon … » exécute la première branche si la condition est vraie, la seconde sinon. Sans « sinon », rien n’est fait quand la condition est fausse.\end{definition}
\begin{exemple}Pour compter les 6 obtenus en 1 000 lancers simulés d’un dé : mettre compteur à 0 ; répéter 1 000 fois : si nombre aléatoire entre 1 et 6 = 6, alors ajouter 1 à compteur. À la fin, la fréquence observée de 6 est compteur : 1 000.\end{exemple}
\begin{savoirfaire}[Écrire et mettre au point]Décomposer la tâche, choisir l’entrée et la sortie, puis tester des valeurs habituelles et des cas limites, comme une valeur égale au seuil d’une condition. Pour un tracé, préciser le point de départ, l’orientation et l’état du stylo.\end{savoirfaire}
\begin{attention}Les conditions composées avec « et » ou « ou », les boucles « répéter jusqu’à », l’usage de plusieurs variables et les blocs personnalisés seront travaillés en Troisième.\end{attention}'''],[
E('Suivre les valeurs',r"Exécuter le script. Quelle valeur affiche-t-il ?",r"x prend d’abord la valeur 4, puis $4+3=7$, puis $7\times2=14$. L’affichage final est donc $\res{14}$. L’ordre des blocs compte.","Écrire la valeur de x après chaque instruction.","assert (4+3)*2==14",figure='script-01'),
E('Une entrée utilisateur',r"Le script demande un nombre x. Donner le résultat pour 5, puis exprimer le résultat pour une entrée quelconque.",r"Pour 5 : $(5-2)\times4=\res{12}$. Pour une entrée $x$, le programme donne $\res{4(x-2)=4x-8}$. Le dernier bloc utilise la valeur déjà diminuée de 2.","Traduire la séquence dans son ordre.","assert (5-2)*4==12 and expand(4*(x-2))==4*x-8",figure='script-02'),
E('Une boucle d’ajouts',r"Exécuter la boucle du script et donner l’affichage.",r"On part de x = 0 et l’on ajoute 5 à chacun des trois tours : 5, 10, 15. Après la boucle, l’affichage est $\res{15}$. Le bloc « dire » est placé une seule fois, après la répétition.","Compter les tours et situer l’affichage.","assert 0+3*5==15",figure='script-03'),
E('Une condition au seuil',r"Le script classe un nombre entier saisi avec la condition « x > 9 ». Donner les messages affichés pour x = 9, puis pour x = 10.",r"Pour 9, la condition $9>9$ est fausse : le message est « $\res{\text{petit}}$ ». Pour 10, $10>9$ est vraie : le message est « $\res{\text{grand}}$ ». Tester la valeur 9 vérifie la frontière de la condition.","Tester aussi la valeur égale au seuil.","assert not 9>9 and 10>9",figure='script-04'),
E('Un produit répété',r"Le script part de x = 3 et double x quatre fois. Donner les valeurs successives de x et l’affichage final.",r"Les valeurs après les tours sont 6, 12, 24 et 48. L’affichage est $\res{48}$. On peut écrire $3\times2^4=48$ ; ajouter quatre fois 2 décrirait un autre programme.","Distinguer répétition d’un produit et répétition d’une somme.","assert 3*2**4==48",figure='script-05'),
E('Compter des 6',r"Le script simule 10 lancers d’un dé. Les nombres aléatoires tirés sont 3, 6, 1, 6, 2, 5, 6, 4, 1 et 3. Que dit le lutin ? Que représente la variable compteur ? Comment modifier le script pour estimer la fréquence de 6 sur 1 000 lancers ?",r"La condition est vraie au 2e, au 4e et au 7e tour : compteur vaut $\res3$, le nombre de 6 obtenus. Pour 1 000 lancers, on remplace 10 par 1 000 dans la boucle et l’on fait dire compteur divisé par 1 000 : c’est la $\res{\text{fréquence observée}}$ de 6, proche de $\frac16$ en général.","Ne modifier la variable que lorsque la condition est vraie.","assert [3,6,1,6,2,5,6,4,1,3].count(6)==3",figure='script-06'),
E('Tracer un carré',r"Le lutin part de (0 ; 0), orienté vers la droite, stylo baissé. Décrire la figure tracée par le script et la position finale du lutin.",r"Il trace quatre segments de 30 pixels, avec un quart de tour dans le sens antihoraire entre deux segments. La figure est un $\res{\text{carré de côté 30 pixels}}$. Il revient en $\res{(0\,;0)}$ et retrouve sa direction initiale après un tour complet.","Additionner les angles de rotation.","assert 4*90==360",figure='script-07'),
E('Tracer un rectangle',r"Avec le même départ et le stylo baissé, décrire le dessin du script. Donner son périmètre.",r"Chaque tour de boucle trace un côté de 50 pixels puis un côté de 20 pixels, avec des quarts de tour. Deux répétitions ferment un $\res{\text{rectangle de 50 sur 20 pixels}}$. Son périmètre vaut $2(50+20)=\res{140}$ pixels.","Lire tout le contenu répété.","assert 2*(50+20)==140 and 2*2*90==360",figure='script-08'),
E('Deux tests de parité',r"Le bloc « reste de x divisé par 2 » vaut 0 lorsque x est pair. Que dit le script pour 18, puis pour 19 ?",r"Le reste de 18 divisé par 2 est nul : le script dit « $\res{\text{pair}}$ ». Le reste de 19 divisé par 2 vaut 1 : il dit « $\res{\text{impair}}$ ». Les deux branches couvrent tous les entiers.","Relier le reste au résultat de la condition.","assert 18%2==0 and 19%2==1",figure='script-09'),
E('Une touche du clavier',r"Ce script est déclenché par la touche espace et ajoute 1 à la variable score. Score vaut 0 au début de la partie et n’est pas réinitialisé par ce script. Quelle valeur obtient-on après cinq appuis ?",r"Chaque appui lance une seule fois le script. Après cinq appuis, score vaut $\res5$. Mettre score à 0 dans ce même script, avant l’ajout, donnerait toujours 1 : l’initialisation doit se faire au début de la partie.","Distinguer initialisation et événement répété.","assert 0+5==5",figure='script-10'),
E('Un triangle équilatéral',r"Le lutin avance de 40 pixels et tourne de $120^\circ$, trois fois de suite. Il part orienté vers la droite, stylo baissé. Justifier la figure obtenue et expliquer pourquoi tourner de $60^\circ$ ne convient pas.",r"Les trois côtés mesurent 40 pixels et les trois rotations font $3\times120=360^\circ$ : le lutin revient au départ. La figure est un $\res{\text{triangle équilatéral}}$, d’angles intérieurs $180-120=60^\circ$. Tourner seulement de $60^\circ$ ne refermerait pas la figure en trois côtés.","Distinguer l’angle intérieur de l’angle de rotation.","assert 3*120==360 and 180-120==60",figure='script-11'),
E('Une interaction simple',r"Le script teste si le lutin touche le lutin Guide. Quel message affiche-t-il selon que le contact est présent ou absent ? Pourquoi faut-il relancer le script pour tester un nouveau contact ?",r"Si le contact est présent au moment du test, il dit « $\res{\text{Bonjour !}}$ » ; sinon, il dit « $\res{\text{Je cherche}}$ ». Le script ne contient pas de répétition : il ne fait qu’un seul test à chaque clic sur le drapeau. Une réaction permanente demanderait de répéter le test.","Repérer le moment où la condition est évaluée.","assert bool(1) and not bool(0)",figure='script-12'),
E('Une dimension saisie',r"Le script demande une longueur c, puis trace une figure. Donner la longueur totale tracée pour c = 25, puis en fonction de c.",r"La boucle trace un carré de côté c. Pour c = 25, la longueur totale vaut $4\times25=\res{100}$ pixels. En général, elle vaut $\res{4c}$ pixels. Il faut saisir une longueur positive.","Relier la variable d’entrée à la figure.","assert 4*25==100",figure='script-13'),
E('Réparer une boucle',r"Un script met s à 0 à l’intérieur de la boucle, puis ajoute 3 à s, quatre fois. Il dit s après la boucle. Expliquer le résultat affiché et corriger le script pour obtenir 12.",r"À chaque tour, s redevient 0 puis vaut 3 : l’affichage est donc $\res3$. Pour accumuler quatre ajouts, on place « mettre s à 0 » avant la boucle et l’on ne répète que l’ajout. On obtient alors $0+4\times3=\res{12}$.","Conserver la mémoire d’un tour au suivant.","assert 0+3==3 and 4*3==12",figure='script-14'),
E('Concevoir et vérifier',r"Écrire un script qui demande un nombre x, puis dit « positif » si $3x+5$ est strictement positif et « nul ou négatif » sinon. Tester les entrées 2, $-2$ et $-\frac53$.",r"Demander x ; si $3\times x+5>0$, alors dire « positif », sinon dire « nul ou négatif ». Pour 2 : $3\times2+5=11$, $\res{\text{positif}}$. Pour $-2$ : $-1$, $\res{\text{nul ou négatif}}$. Pour $-\frac53$ : 0, $\res{\text{nul ou négatif}}$ ; ce dernier test vérifie le seuil de la condition.","Tester une valeur de chaque côté du seuil et le seuil lui-même.","assert [3*a+5 for a in [2,-2,Rational(-5,3)]]==[11,-1,0]",figure='script-15')
],reperes=['Variable, séquences et entrées','Conditions et cas limites','Boucles et constructions géométriques','Événements, interactions et mise au point'],deco='algorithmique')
